      @switch (context.state()) {
        @case ('loading') {
          <app-status-message kind="loading" />
        }
        @case ('error') {
          <app-status-message kind="error" (retry)="context.reload()" />
        }
        @case ('notAvailable') {
          <app-country-not-available />
        }
        @case ('ready') {
          @let wizard = wizardTexts();
          @if (wizard) {
            @if (currentStep(); as step) {
