  background: var(--color-surface-soft);
  font-weight: 600;
}

.error {
  border-left-color: var(--color-error);
  background: var(--color-error-surface);
  color: var(--color-error);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 2rem;
}

@if (title(); as pageTitle) {
  <app-step-heading [text]="pageTitle" />

  <div class="summary">
    <!-- Data of step 1 (REQ-03.1 to REQ-03.3, REQ-03.6) -->
    <section class="summary-section summary-data">
      @if (dataTexts(); as texts) {
        @for (section of sections(); track section.id) {
          <h2 [id]="'summary-' + section.id">{{ section.legend }}</h2>
          <dl [attr.aria-labelledby]="'summary-' + section.id">
            @for (item of section.items; track item.key) {
              <div class="item">
                <dt>{{ item.label }}</dt>
                <dd>{{ item.display }}</dd>
              </div>
            }
          </dl>
        }
        <button type="button" (click)="editData()" [disabled]="processing()">
          {{ texts.editDataLabel }}
        </button>
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>

    <!-- Chosen plan and final price (REQ-03.4, REQ-03.5) -->
    <section class="summary-section summary-plan" aria-labelledby="summary-plan-heading">
      @if (planTexts(); as texts) {
        <h2 id="summary-plan-heading">{{ texts.planHeading }}</h2>
        @if (planState(); as state) {
          @if (state.kind === 'loading') {
            <app-status-message kind="loading" />
          } @else if (state.kind === 'error') {
            <app-status-message kind="error" (retry)="planResource.reload()" />
          } @else {
            <p class="plan-name">{{ state.plan.plan.name }}</p>
            @if (state.plan.plan.shortDescription) {
              <p>{{ state.plan.plan.shortDescription }}</p>
            }
            @if (state.plan.plan.coverages.length > 0) {
              <p class="list-title" id="summary-coverages">{{ texts.coveragesHeading }}</p>
              <ul aria-labelledby="summary-coverages">
                @for (coverage of state.plan.plan.coverages; track $index) {
                  <li>{{ coverage }}</li>
                }
              </ul>
            }
            @if (state.plan.plan.benefits.length > 0) {
              <p class="list-title" id="summary-benefits">{{ texts.benefitsHeading }}</p>
              <ul aria-labelledby="summary-benefits">
                @for (benefit of state.plan.plan.benefits; track $index) {
                  <li>{{ benefit }}</li>
                }
              </ul>
            }
            <p class="final-price">
              <span>{{ texts.finalPriceLabel }}</span>&ngsp;
              <strong>{{ state.plan.formattedPrice }}</strong>
            </p>
          }
        }
        <button type="button" (click)="changePlan()" [disabled]="processing()">
          {{ texts.changePlanLabel }}
        </button>
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>

    <!-- Terms and conditions (REQ-03.15 to REQ-03.18) -->
    <section class="summary-section summary-terms" aria-labelledby="summary-terms-heading">
      @if (termsTexts(); as texts) {
        <h2 id="summary-terms-heading">{{ texts.termsHeading }}</h2>
        @if (termsState(); as state) {
          @if (state.kind === 'loading') {
            <app-status-message kind="loading" />
          } @else if (state.kind === 'error') {
            <app-status-message kind="error" (retry)="termsResource.reload()" />
          } @else if (state.kind === 'unavailable') {
            <app-status-message kind="message" [message]="texts.termsUnavailableMessage" />
          } @else {
            <div
              class="terms-region"
              role="region"
              tabindex="0"
              aria-labelledby="summary-terms-heading"
            >
              <app-terms-blocks [document]="state.document" />
            </div>
          }
          <div class="accept">
            <input
              type="checkbox"
              id="accept-terms"
              [checked]="termsAccepted()"
              [disabled]="state.kind !== 'ready' || processing()"
              (change)="onTermsChange($event)"
            />
            <label for="accept-terms">{{ texts.acceptTermsLabel }}</label>
          </div>
        }
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>

    <!-- Simulated gateway and payment (REQ-03.19 to REQ-03.25, REQ-03.30, REQ-03.35) -->
    <section class="summary-section summary-payment">
      @if (paymentTexts(); as texts) {
        <fieldset class="gateway">
          <legend>{{ texts.gatewayLegend }}</legend>
          <div class="outcome">
            <input
              type="radio"
              name="payment-outcome"
              id="outcome-approved"
              value="approved"
              [checked]="outcome() === 'approved'"
              [disabled]="processing()"
              (change)="chooseOutcome('approved')"
            />
            <label for="outcome-approved">{{ texts.approvedOptionLabel }}</label>
          </div>
          <div class="outcome">
            <input
              type="radio"
              name="payment-outcome"
              id="outcome-rejected"
              value="rejected"
              [checked]="outcome() === 'rejected'"
              [disabled]="processing()"
              (change)="chooseOutcome('rejected')"
            />
            <label for="outcome-rejected">{{ texts.rejectedOptionLabel }}</label>
          </div>
        </fieldset>

        @if (!termsAccepted() && termsTexts(); as hintTexts) {
          <p id="pay-hint" class="hint">{{ hintTexts.acceptTermsHint }}</p>
        }
        <button
          type="button"
          class="pay btn-primary"
          [disabled]="payNativelyDisabled()"
          [attr.aria-disabled]="processing() ? 'true' : null"
          [attr.aria-busy]="processing() ? 'true' : null"
          [attr.aria-describedby]="payDescribedBy()"
          (click)="pay()"
        >
          {{ texts.payLabel }}
        </button>
        <p id="pay-status" class="processing" aria-live="polite">
          @if (processing()) {
            {{ texts.processingMessage }}
          }
        </p>
        @if (payment() === 'rejected') {
          <p id="pay-rejected" class="rejected" role="alert">{{ texts.rejectedMessage }}</p>
        }
      } @else {
        <app-status-message kind="message" [message]="genericErrorMessage()" />
      }
    </section>
  </div>
} @else {
  <app-status-message kind="message" [message]="genericErrorMessage()" />
}
/* One column at every width; no horizontal scroll from 320 px (REQ-03.36). */
.summary {
  display: grid;
  gap: 1.5rem;
  max-width: 48rem;
}

/* Each section is a card. */
.summary-section {
  min-width: 0;
  padding: var(--card-padding);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: #ffffff;
}

h2 {
  margin: 0 0 0.75rem;
}

dl + h2 {
  margin-top: 1.5rem;
}

dl {
  margin: 0 0 1.25rem;
}

.item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.5rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--color-border);
}

dt {
  color: var(--color-text-muted);
  font-weight: 600;
}

dd {
  margin: 0;
}

.plan-name {
  margin: 0 0 0.5rem;
  font-size: 1.125rem;
  font-weight: 700;
}

.list-title {
  margin: 1rem 0 0.25rem;
  font-weight: 700;
}

ul {
  margin: 0;
  padding-left: 1.25rem;
}

li::marker {
  color: var(--color-primary);
}

/* Final price stands out in a light-blue block (dark blue on surface: 8.76:1). */
.final-price {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.25rem 1rem;
  margin: 1.25rem 0;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  background: var(--color-surface);
  color: var(--color-primary-dark);
  font-weight: 700;
}

.final-price strong {
  font-size: 1.75rem;
  font-variant-numeric: tabular-nums;
}

/* Inline, scrollable and focusable with the keyboard (REQ-03.16, Q-03.13). */
.terms-region {
  max-height: 16rem;
  overflow-y: auto;
  padding: 0.75rem 1rem;
  border: 1px solid var(--color-border-strong);
  border-radius: var(--radius-md);
  background: var(--color-surface-soft);
}

.accept,
.outcome {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-top: 1rem;
}

input[type='checkbox'],
input[type='radio'] {
  /* Never shrink inside the flex rows when the label wraps (REQ-03.36, D-E2E-1). */
  flex: none;
  width: 24px;
  height: 24px;
  margin: 0;
  accent-color: var(--color-primary);
}

/* Simulated gateway: a dashed card; the legend floats so it sits inside it. */
.gateway {
  display: grid;
  margin: 0 0 1.25rem;
  padding: 1rem 1.25rem 1.25rem;
  border: 1px dashed var(--color-border-strong);
  border-radius: var(--radius-md);
  background: var(--color-surface-soft);
  min-width: 0;
}

.gateway legend {
  float: left;
  width: 100%;
  padding: 0;
  font-weight: 700;
}

.gateway .outcome {
  margin-top: 0.75rem;
}

.hint {
  margin: 0 0 0.75rem;
  color: var(--color-text-muted);
}

.processing:empty {
  display: none;
}

.processing,
.rejected {
  margin: 1rem 0 0;
  font-weight: 600;
}

.processing {
  color: var(--color-primary-dark);
}

.rejected {
  padding: 0.75rem 1rem;
  border-left: 4px solid var(--color-error);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  background: var(--color-error-surface);
  color: var(--color-error);
}

@media (max-width: 30rem) {
  .item {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .pay {
    width: 100%;
  }
}
import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { Router } from '@angular/router';
import { CountryContext } from '../../core/country/country-context';
import { WizardStorage } from '../../core/storage/wizard-storage';
import { formatPrice } from '../../domain/pricing/format-price';
import { StatusMessage } from '../../shared/status-message';
import { StepHeading } from '../../shared/step-heading';

/**
 * Confirmation, `/:country/confirmation` (REQ-03.25, REQ-03.27, REQ-03.28). Not a step (D7).
 * It shows only what was copied at payment time: quote number, plan name and price paid, without
 * personal data. Reloading shows it again; "nueva cotización" deletes it and opens an empty
 * step 1 (step 1 data was already deleted after the payment).
 */
@Component({
  selector: 'app-confirmation-page',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [StatusMessage, StepHeading],
  template: `
    @if (view(); as v) {
      @if (v.kind === 'ready') {
        <app-step-heading [text]="v.texts.title" />
        <div class="success-card">
          <dl class="confirmation">
            <div class="item">
              <dt>{{ v.texts.quoteNumberLabel }}</dt>
              <dd class="quote-number">{{ v.quoteNumber }}</dd>
            </div>
            <div class="item">
              <dt>{{ v.texts.planLabel }}</dt>
              <dd>{{ v.planName }}</dd>
            </div>
            <div class="item">
              <dt>{{ v.texts.paidPriceLabel }}</dt>
              <dd>{{ v.paidPrice }}</dd>
            </div>
          </dl>
        </div>
        <button type="button" class="btn-primary" (click)="newQuote()">
          {{ v.texts.newQuoteLabel }}
        </button>
      } @else {
        <app-status-message kind="message" [message]="v.message" />
      }
    }
  `,
  /*
   * Success card (D12): light-blue surface with a primary accent and a decorative check drawn
   * with CSS (empty pseudo-elements, no text). Dark blue on surface: 8.76:1.
   */
  styles: `
    .success-card {
      position: relative;
      max-width: 40rem;
      margin: 0 0 2rem;
      padding: 4.5rem var(--card-padding) var(--card-padding);
      border-top: 6px solid var(--color-primary);
      border-radius: var(--radius-md);
      background: var(--color-surface);
    }
    .success-card::before {
      content: '';
      position: absolute;
      top: 1.25rem;
      left: var(--card-padding);
      width: 2.5rem;
      height: 2.5rem;
      border-radius: 50%;
      background: var(--color-primary-dark);
    }
    .success-card::after {
      content: '';
      position: absolute;
      top: calc(1.25rem + 0.6rem);
      left: calc(var(--card-padding) + 0.95rem);
      width: 0.6rem;
      height: 1.05rem;
      border: solid #ffffff;
      border-width: 0 3px 3px 0;
      transform: rotate(45deg);
    }
    .confirmation {
      display: grid;
      gap: 0.75rem;
      margin: 0;
    }
    .item {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
      gap: 0.5rem;
      padding-bottom: 0.75rem;
      border-bottom: 1px solid rgb(0 51 160 / 0.15);
    }
    .item:last-child {
      padding-bottom: 0;
      border-bottom: 0;
    }
    dt {
      color: var(--color-text-muted);
      font-weight: 600;
    }
    dd {
      margin: 0;
      font-weight: 600;
    }
    .quote-number {
      color: var(--color-primary-dark);
      font-size: 1.5rem;
      font-weight: 700;
      letter-spacing: 0.05em;
    }
    @media (max-width: 30rem) {
      .item {
        grid-template-columns: 1fr;
        gap: 0.125rem;
      }
    }
  `,
})
export class ConfirmationPage {
  private readonly context = inject(CountryContext);
  private readonly storage = inject(WizardStorage);
  private readonly router = inject(Router);

  protected readonly view = computed(() => {
    const config = this.context.config();
    if (!config) {
      return null;
    }
    const group = config.texts.confirmation;
    const confirmation = this.storage.readConfirmation(config.country.code);
    if (group.status !== 'ok' || !confirmation) {
      return { kind: 'configError' as const, message: config.genericErrorMessage };
    }
    return {
      kind: 'ready' as const,
      texts: group.texts,
      quoteNumber: confirmation.quoteNumber,
      planName: confirmation.planName,
      paidPrice: formatPrice(
        confirmation.finalPrice,
        config.country.intlLocale,
        confirmation.currency,
      ),
    };
  });

  /** REQ-03.27, REQ-03.28: deletes the confirmation and starts again at an empty step 1. */
  protected newQuote(): void {
    const code = this.context.code();
    this.storage.remove(code, 'confirmation');
    void this.router.navigate(['/', code, 'form']);
  }
}

