 * Palette, shapes, spacing and motion live in custom properties; components reuse them.
 * Contrast (WCAG AA) of each text/background pair is noted next to the token.
 * Font: Figtree (OFL), self-hosted through `@fontsource-variable/figtree` (angular.json `styles`),
 * so the CSP `default-src 'self'` does not change (D13).
 * No horizontal scroll from 320 px (REQ-01.33, REQ-02.29, REQ-03.36).
 */

:root {
  /* Brand */
  --color-primary: #2d6df6; /* 4.54:1 on white; 3.75:1 on surface (large text / UI only) */
  --color-primary-dark: #0033a0; /* 10.6:1 on white; 8.76:1 on surface */
  --color-accent: #e3e829; /* CTA background */
  --color-accent-hover: #d4d91f; /* on-accent on it: 7.17:1 */
  --color-accent-active: #c9ce14; /* on-accent on it: 6.43:1 */
  --color-on-accent: #26328c; /* 8.26:1 on accent; 10.95:1 on white; 9.05:1 on surface */
  --color-surface: #dfeaff; /* hero, selected plan, highlighted blocks */
  --color-surface-strong: #ccdcff; /* pressed secondary button: on-accent 7.95:1 */
  --color-surface-soft: #f5f8ff;

  /* Text and lines */
  --color-text: #1c1c24; /* 16.9:1 on white; 13.98:1 on surface */
  --color-text-muted: #3f3f41; /* 10.5:1 on white; 8.68:1 on surface */
  --color-link: #0b5fff; /* 5.13:1 on white */
  --color-border: #e3eaf7; /* decorative card borders */
  --color-border-strong: #6b6b70; /* inputs and UI boundaries: 5.3:1 on white, 4.38:1 on surface */
  --color-focus: #0033a0; /* focus ring: 10.6:1 on white, 8.76:1 on surface, 8:1 on accent */
  --focus-halo: 0 0 0 4px rgb(45 109 246 / 0.22); /* decorative halo, the outline is the indicator */

  /* States */
  --color-error: #b3261e; /* 6.54:1 on white; 5.92:1 on error surface */
  --color-error-surface: #fdf1f0;
  --color-disabled-bg: #f2f2f2;
  --color-disabled-text: #5c5c61; /* 5.94:1 on disabled background */

  /* Shapes, elevation and layout (4/8 px spacing scale) */
  --radius-sm: 0.625rem;
  --radius-md: 0.5rem;
  --radius-lg: 1rem;
  --radius-pill: 1.75rem;
  --shadow-sm: 0 1px 2px rgb(0 51 160 / 0.06), 0 2px 8px rgb(0 51 160 / 0.08);
  --shadow-md: 0 4px 16px rgb(0 51 160 / 0.12);
  --container-max: 72rem;
  --gutter: 1rem;
  --card-padding: 1.25rem;
  --font-family: 'Figtree Variable', system-ui, 'Segoe UI', Roboto, sans-serif;

  /* Motion */
  --ease-out: cubic-bezier(0.2, 0.7, 0.3, 1);
  --duration-fast: 150ms;
  --duration-view: 220ms;
}

@media (min-width: 48rem) {
  :root {
    --gutter: 1.5rem;
    --card-padding: 1.75rem;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-family: var(--font-family);
  line-height: 1.5;
  color: var(--color-text);
  background: #ffffff;
  -webkit-text-size-adjust: 100%;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

body {
  margin: 0;
  font-size: 1rem;
  overflow-wrap: anywhere;
}

@media (min-width: 48rem) {
  body {
    font-size: 1.0625rem;
  }
}

img,
svg {
  max-width: 100%;
}

/* Headings: primary blue, bold (SURA reference). */
h1,
h2 {
  color: var(--color-primary);
  font-weight: 800;
  line-height: 1.15;
}

/*
 * Every screen heading sits on a full-width light-blue hero band. The band is painted with
 * border-image outset, which is ink overflow: it never adds horizontal scroll.
 * h1 is at least 32 px bold, so #2D6DF6 on the hero (3.75:1) is large text (>= 3:1).
 */
h1,
.hero-bleed {
  border-image: linear-gradient(var(--color-surface), var(--color-surface)) fill 0 / 0 / 0 100vmax;
}

h1 {
  margin: 0 0 2rem;
  padding: 1.5rem 0 2rem;
  font-size: clamp(2rem, 1.5rem + 2.4vw, 3rem);
  letter-spacing: -0.02em;
}

h2 {
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

/* Visible focus everywhere, dark blue so it keeps >= 3:1 on white, hero and yellow. */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

h1:focus {
  outline: none;
}

h1:focus-visible {
  outline: 3px solid var(--color-focus);
}

