SP="C:/Users/JORGEA~1/AppData/Local/Temp/claude/7c00b3cd46447d40/e47a27f0-74c7-4957-994a-94c086d65178/scratchpad"; cat > "$SP/d13/visual.cjs" <<'EOF'
// Throwaway visual check (not part of the repo).
const { chromium } = require(process.argv[2]);
const out = process.argv[3];
const base = process.argv[4] || 'http://localhost:4300';
const widths = (process.argv[5] || '320,375,1280').split(',').map(Number);

async function metrics(page, name) {
  const m = await page.evaluate(() => {
    const small = [];
    document.querySelectorAll('button, a, input[type="checkbox"], input[type="radio"], input, select').forEach((el) => {
      const r = el.getBoundingClientRect();
      if (r.width === 0 && r.height === 0) return;
      if (r.width < 24 || r.height < 24) small.push(`${el.tagName}#${el.id} ${r.width}x${r.height}`);
      if (el.tagName === 'BUTTON' && r.height < 44) small.push(`button<44 ${el.textContent.trim()} ${r.height}`);
    });
    const logo = document.querySelector('.brand-logo')?.getBoundingClientRect();
    return {
      sw: document.documentElement.scrollWidth,
      cw: document.documentElement.clientWidth,
      font: getComputedStyle(document.body).fontFamily.slice(0, 20),
      figtree: document.fonts.check('16px "Figtree Variable"'),
      logo: logo ? `${Math.round(logo.width)}x${Math.round(logo.height)}@${Math.round(logo.left)}` : null,
      small,
    };
  });
  console.log(name, JSON.stringify(m));
}

(async () => {
  const browser = await chromium.launch({ channel: 'chrome' });
  const external = new Set();
  for (const width of widths) {
    const ctx = await browser.newContext({ viewport: { width, height: 860 } });
    const page = await ctx.newPage();
    page.on('request', (r) => { const u = new URL(r.url()); if (!['localhost', '127.0.0.1'].includes(u.hostname) && u.protocol !== 'data:') external.add(r.url()); });
    const shot = async (n, full = true) => {
      await page.waitForTimeout(350);
      await metrics(page, `${n}@${width}`);
      await page.screenshot({ path: `${out}/${n}-${width}.png`, fullPage: full });
    };
    await page.goto(base + '/');
    await page.getByRole('link').first().waitFor();
    await page.evaluate(() => document.fonts.ready);
    await shot('01-countries');
    await page.getByRole('link').first().hover();
    await shot('01b-countries-hover', false);
    await page.goto(base + '/pe');
    await page.getByRole('link').first().waitFor();
    await shot('02-not-available');
    await page.goto(base + '/co/form');
    await page.getByLabel('Placa').waitFor();
    await page.keyboard.press('Tab');
    await page.keyboard.press('Tab');
    await shot('03a-form-empty-focus', false);
    await page.getByRole('button', { name: 'Continuar' }).click();
    await shot('03b-form-errors');
    await page.getByLabel('Tipo de documento').selectOption('cc');
    await page.getByLabel('Número de documento').fill('1234567890');
    await page.getByLabel('Fecha de nacimiento').fill('2000-05-10');
    await page.getByLabel('Ciudad').selectOption('bogota');
    await page.getByLabel('Autorizo el tratamiento de mis datos personales').check();
    await page.getByLabel('Placa').fill('ABC123');
    await page.getByLabel('Marca').selectOption('make_a');
    await page.getByLabel('Año del vehículo').fill('2018');
    await page.getByLabel('Placa').focus();
    await shot('03c-form-filled', false);
    await page.getByRole('button', { name: 'Continuar' }).click();
    await page.getByRole('radio').first().waitFor();
    await shot('04a-plans');
    await page.getByRole('radio').nth(1).check();
    await shot('04b-plans-selected');
    await page.getByRole('button', { name: 'Continuar' }).click();
    await page.locator('.terms-region').waitFor();
    await shot('05-summary');
    await page.getByRole('checkbox').check();
    await page.getByRole('radio').first().check();
    await page.locator('.pay').click();
    await page.waitForURL(/confirmation/, { timeout: 10000 });
    await shot('06-confirmation');
    // Loading states: delay the content API.
    await page.route('**/api/**', async (route) => { await new Promise((r) => setTimeout(r, 2500)); await route.continue(); });
    await page.goto(base + '/');
    await page.getByRole('status').first().waitFor();
    await shot('07a-loading-home', false);
    await page.goto(base + '/cl/form');
    await page.waitForTimeout(300);
    await shot('07b-loading-country', false);
    await page.unroute('**/api/**');
    await ctx.close();
  }
  console.log('external requests:', JSON.stringify([...external]));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
